-- PostgreSQL conversion of voamamy_db.sql
-- Tables, data, constraints, triggers, procedures and views preserved.
BEGIN;
SET standard_conforming_strings = off;
SET client_encoding = 'UTF8';

-- Nettoyage des objets existants
DROP VIEW IF EXISTS v_solde_epargne_membre CASCADE;
DROP VIEW IF EXISTS v_solde_caisse_cycle CASCADE;
DROP VIEW IF EXISTS v_situation_credits CASCADE;
DROP VIEW IF EXISTS v_resume_cycle CASCADE;
DROP VIEW IF EXISTS v_penalites_encaissement_cycle CASCADE;
DROP VIEW IF EXISTS v_mouvements_caisse CASCADE;
DROP VIEW IF EXISTS v_interets_encaissement_cycle CASCADE;
DROP VIEW IF EXISTS v_historique_solde_epargne CASCADE;
DROP VIEW IF EXISTS v_epargne_membre_cycle CASCADE;
DROP TABLE IF EXISTS voamami CASCADE;
DROP TABLE IF EXISTS utilisateurs CASCADE;
DROP TABLE IF EXISTS soldes_epargne_seance CASCADE;
DROP TABLE IF EXISTS seances CASCADE;
DROP TABLE IF EXISTS remboursements CASCADE;
DROP TABLE IF EXISTS rapports CASCADE;
DROP TABLE IF EXISTS presences CASCADE;
DROP TABLE IF EXISTS penalites CASCADE;
DROP TABLE IF EXISTS partage_benefices CASCADE;
DROP TABLE IF EXISTS mouvements_caisse CASCADE;
DROP TABLE IF EXISTS membres CASCADE;
DROP TABLE IF EXISTS historique CASCADE;
DROP TABLE IF EXISTS epargnes CASCADE;
DROP TABLE IF EXISTS cycles CASCADE;
DROP TABLE IF EXISTS credits CASCADE;
DROP TABLE IF EXISTS agr CASCADE;

CREATE TABLE agr (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    libelle varchar(100) NOT NULL,
    description varchar(255),
    actif SMALLINT NOT NULL DEFAULT 1,
    PRIMARY KEY (id),
    CONSTRAINT libelle UNIQUE (libelle)
);

CREATE TABLE credits (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    cycle_id BIGINT NOT NULL,
    seance_id BIGINT NOT NULL,
    membre_id BIGINT NOT NULL,
    agr_id BIGINT,
    date_credit date NOT NULL,
    montant_capital decimal(15,2) NOT NULL,
    taux_interet decimal(5,2) NOT NULL,
    montant_interet decimal(15,2) NOT NULL,
    montant_total decimal(15,2) NOT NULL,
    date_echeance date NOT NULL,
    statut VARCHAR(20) NOT NULL DEFAULT 'EN_COURS',
    observation text,
    created_at timestamp NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    CONSTRAINT chk_montant_credit CHECK (montant_capital > 0),
    CONSTRAINT chk_interet_credit CHECK (montant_interet >= 0),
    CONSTRAINT chk_total_credit CHECK (montant_total = montant_capital + montant_interet),
    CONSTRAINT chk_credits_statut_enum CHECK (statut IN ('EN_COURS', 'REMBOURSE', 'EN_RETARD'))
);

CREATE TABLE cycles (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    voamami_id BIGINT NOT NULL,
    numero_cycle INTEGER NOT NULL,
    date_debut date NOT NULL,
    date_fin_prevue date,
    date_cloture date,
    statut VARCHAR(20) NOT NULL DEFAULT 'PREPARATION',
    montant_part_epargne decimal(15,2) NOT NULL,
    montant_penalite decimal(15,2) NOT NULL DEFAULT 0.00,
    taux_interet decimal(5,2) NOT NULL DEFAULT 10.00,
    duree_credit_mois SMALLINT NOT NULL DEFAULT 3,
    created_at timestamp NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    CONSTRAINT uq_cycle_voamami_numero UNIQUE (voamami_id,numero_cycle),
    CONSTRAINT chk_montant_part CHECK (montant_part_epargne > 0),
    CONSTRAINT chk_montant_penalite CHECK (montant_penalite >= 0),
    CONSTRAINT chk_taux_interet CHECK (taux_interet >= 0),
    CONSTRAINT chk_duree_credit CHECK (duree_credit_mois > 0),
    CONSTRAINT chk_cycles_statut_enum CHECK (statut IN ('PREPARATION', 'OUVERT', 'CLOTURE'))
);

CREATE TABLE epargnes (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    cycle_id BIGINT NOT NULL,
    seance_id BIGINT NOT NULL,
    membre_id BIGINT NOT NULL,
    nombre_parts SMALLINT NOT NULL,
    montant_part decimal(15,2) NOT NULL,
    montant_total decimal(15,2) NOT NULL,
    date_epargne date NOT NULL,
    created_at timestamp NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    CONSTRAINT chk_nombre_parts CHECK (nombre_parts between 1 and 5),
    CONSTRAINT chk_montant_epargne CHECK (montant_total > 0)
);

CREATE TABLE historique (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    utilisateur_id BIGINT,
    action varchar(100) NOT NULL,
    table_concernee varchar(100),
    enregistrement_id BIGINT,
    description text,
    date_action TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
);

CREATE TABLE membres (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    voamami_id BIGINT NOT NULL,
    numero_membre SMALLINT NOT NULL,
    nom varchar(100) NOT NULL,
    prenom varchar(100),
    sexe VARCHAR(20),
    date_naissance date,
    telephone varchar(30),
    adresse varchar(255),
    profession varchar(100),
    role_bureau VARCHAR(20) NOT NULL DEFAULT 'MEMBRE',
    cycle_actif_id BIGINT,
    solde_epargne decimal(15,2) NOT NULL DEFAULT 0.00,
    actif SMALLINT NOT NULL DEFAULT 1,
    created_at timestamp NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    CONSTRAINT uq_membre_numero UNIQUE (voamami_id,numero_membre),
    CONSTRAINT chk_numero_membre CHECK (numero_membre between 1 and 25),
    CONSTRAINT chk_solde_epargne CHECK (solde_epargne >= 0),
    CONSTRAINT chk_membres_sexe_enum CHECK (sexe IN ('M', 'F')),
    CONSTRAINT chk_membres_role_bureau_enum CHECK (role_bureau IN ('PRESIDENT', 'SECRETAIRE', 'TRESORIER', 'MEMBRE'))
);

CREATE TABLE mouvements_caisse (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    cycle_id BIGINT NOT NULL,
    seance_id BIGINT NOT NULL,
    membre_id BIGINT,
    type_mouvement VARCHAR(21) NOT NULL,
    montant decimal(15,2) NOT NULL,
    sens VARCHAR(20) NOT NULL,
    epargne_id BIGINT,
    credit_id BIGINT,
    remboursement_id BIGINT,
    penalite_id BIGINT,
    description varchar(255),
    date_mouvement date NOT NULL,
    created_at timestamp NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    CONSTRAINT chk_caisse_montant CHECK (montant > 0),
    CONSTRAINT chk_mouvements_caisse_type_mouvement_enum CHECK (type_mouvement IN ('EPARGNE', 'CREDIT', 'REMBOURSEMENT_CAPITAL', 'REMBOURSEMENT_INTERET', 'PENALITE')),
    CONSTRAINT chk_mouvements_caisse_sens_enum CHECK (sens IN ('ENTREE', 'SORTIE'))
);

CREATE TABLE partage_benefices (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    cycle_id BIGINT NOT NULL,
    membre_id BIGINT NOT NULL,
    capital_membre decimal(15,2) NOT NULL DEFAULT 0.00,
    part_interets decimal(15,2) NOT NULL DEFAULT 0.00,
    part_penalites decimal(15,2) NOT NULL DEFAULT 0.00,
    montant_total_partage decimal(15,2) NOT NULL DEFAULT 0.00,
    date_partage date NOT NULL,
    created_at timestamp NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    CONSTRAINT uq_partage UNIQUE (cycle_id,membre_id)
);

CREATE TABLE penalites (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    cycle_id BIGINT NOT NULL,
    seance_id BIGINT NOT NULL,
    membre_id BIGINT NOT NULL,
    type_penalite varchar(100) NOT NULL,
    montant decimal(15,2) NOT NULL,
    date_penalite date NOT NULL,
    motif varchar(255),
    statut VARCHAR(20) NOT NULL DEFAULT 'IMPAYEE',
    created_at timestamp NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    CONSTRAINT chk_penalite_montant CHECK (montant >= 0),
    CONSTRAINT chk_penalites_statut_enum CHECK (statut IN ('IMPAYEE', 'PAYEE'))
);

CREATE TABLE presences (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    seance_id BIGINT NOT NULL,
    membre_id BIGINT NOT NULL,
    statut VARCHAR(20) NOT NULL DEFAULT 'PRESENT',
    observation varchar(255),
    created_at timestamp NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    CONSTRAINT uq_presence UNIQUE (seance_id,membre_id),
    CONSTRAINT chk_presences_statut_enum CHECK (statut IN ('PRESENT', 'ABSENT', 'EXCUSE'))
);

CREATE TABLE rapports (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    cycle_id BIGINT NOT NULL,
    seance_id BIGINT,
    type_rapport VARCHAR(20) NOT NULL,
    titre varchar(255) NOT NULL,
    contenu TEXT,
    date_generation TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    utilisateur_id BIGINT,
    PRIMARY KEY (id),
    CONSTRAINT chk_rapports_type_rapport_enum CHECK (type_rapport IN ('SEANCE', 'EPARGNE', 'CREDIT', 'REMBOURSEMENT', 'CLOTURE_CYCLE'))
);

CREATE TABLE remboursements (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    credit_id BIGINT NOT NULL,
    cycle_id BIGINT NOT NULL,
    seance_id BIGINT NOT NULL,
    membre_id BIGINT NOT NULL,
    date_remboursement date NOT NULL,
    montant_principal decimal(15,2) NOT NULL DEFAULT 0.00,
    montant_interet decimal(15,2) NOT NULL DEFAULT 0.00,
    montant decimal(15,2) NOT NULL,
    observation text,
    created_at timestamp NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    CONSTRAINT chk_remb_total CHECK (montant = montant_principal + montant_interet),
    CONSTRAINT chk_remb_positif CHECK (montant > 0)
);

CREATE TABLE seances (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    cycle_id BIGINT NOT NULL,
    numero_seance INTEGER NOT NULL,
    date_seance date NOT NULL,
    statut VARCHAR(20) NOT NULL DEFAULT 'OUVERTE',
    observation text,
    created_at timestamp NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    CONSTRAINT uq_seance_cycle_numero UNIQUE (cycle_id,numero_seance),
    CONSTRAINT chk_seances_statut_enum CHECK (statut IN ('OUVERTE', 'CLOTUREE'))
);

CREATE TABLE soldes_epargne_seance (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    cycle_id BIGINT NOT NULL,
    seance_id BIGINT NOT NULL,
    membre_id BIGINT NOT NULL,
    parts_cumulees INTEGER NOT NULL DEFAULT 0,
    epargne_seance decimal(15,2) NOT NULL DEFAULT 0.00,
    solde_epargne decimal(15,2) NOT NULL DEFAULT 0.00,
    date_enregistrement TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    CONSTRAINT uq_solde_membre_seance UNIQUE (seance_id,membre_id)
);

CREATE TABLE utilisateurs (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    nom varchar(100) NOT NULL,
    prenom varchar(100),
    email varchar(150) NOT NULL,
    mot_de_passe varchar(255) NOT NULL,
    role VARCHAR(20) NOT NULL DEFAULT 'AGENT_FID',
    actif SMALLINT NOT NULL DEFAULT 1,
    created_at timestamp NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    CONSTRAINT email UNIQUE (email),
    CONSTRAINT chk_utilisateurs_role_enum CHECK (role IN ('ADMINISTRATEUR', 'AGENT_FID'))
);

CREATE TABLE voamami (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    code varchar(50) NOT NULL,
    nom varchar(150) NOT NULL,
    localite varchar(150),
    fokontany varchar(150),
    commune varchar(150),
    district varchar(150),
    region varchar(150),
    date_creation date NOT NULL,
    statut VARCHAR(20) NOT NULL DEFAULT 'ACTIF',
    agent_responsable_id BIGINT,
    created_at timestamp NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    CONSTRAINT code UNIQUE (code),
    CONSTRAINT chk_voamami_statut_enum CHECK (statut IN ('ACTIF', 'INACTIF'))
);

