-- ============================ TRIGGERS ============================

CREATE OR REPLACE FUNCTION fn_credit_before_insert() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_taux NUMERIC(5,2); v_duree SMALLINT; v_statut_cycle VARCHAR(20); v_cycle_seance BIGINT; v_statut_seance VARCHAR(20); v_solde NUMERIC(15,2); v_cycle_membre BIGINT; v_max_credit NUMERIC(15,2); v_caisse NUMERIC(15,2); v_credit_actif INTEGER;
BEGIN
 SELECT statut,taux_interet,duree_credit_mois INTO v_statut_cycle,v_taux,v_duree FROM cycles WHERE id=NEW.cycle_id;
 IF v_statut_cycle IS DISTINCT FROM 'OUVERT' THEN RAISE EXCEPTION 'Le cycle doit etre ouvert pour accorder un credit.'; END IF;
 SELECT cycle_id,statut INTO v_cycle_seance,v_statut_seance FROM seances WHERE id=NEW.seance_id;
 IF v_cycle_seance IS DISTINCT FROM NEW.cycle_id THEN RAISE EXCEPTION 'La seance ne correspond pas au cycle.'; END IF;
 IF v_statut_seance IS DISTINCT FROM 'OUVERTE' THEN RAISE EXCEPTION 'La seance est deja cloturee.'; END IF;
 SELECT solde_epargne,cycle_actif_id INTO v_solde,v_cycle_membre FROM membres WHERE id=NEW.membre_id AND actif=1;
 IF v_cycle_membre IS DISTINCT FROM NEW.cycle_id THEN RAISE EXCEPTION 'Le membre ne correspond pas au cycle actif.'; END IF;
 SELECT COUNT(*) INTO v_credit_actif FROM credits WHERE membre_id=NEW.membre_id AND cycle_id=NEW.cycle_id AND statut IN ('EN_COURS','EN_RETARD');
 IF v_credit_actif>0 THEN RAISE EXCEPTION 'Le membre a deja un credit non solde : impossible d''en accorder un nouveau.'; END IF;
 v_max_credit := COALESCE(v_solde,0)*3;
 IF NEW.montant_capital>v_max_credit THEN RAISE EXCEPTION 'Le credit depasse 3 fois le solde d epargne du membre.'; END IF;
 SELECT COALESCE(SUM(CASE WHEN sens='ENTREE' THEN montant ELSE -montant END),0) INTO v_caisse FROM mouvements_caisse WHERE cycle_id=NEW.cycle_id;
 IF NEW.montant_capital>v_caisse THEN RAISE EXCEPTION 'La caisse du VOAMAMY ne dispose pas de fonds suffisants pour ce credit.'; END IF;
 NEW.taux_interet:=v_taux; NEW.montant_interet:=NEW.montant_capital*NEW.taux_interet/100; NEW.montant_total:=NEW.montant_capital+NEW.montant_interet; NEW.date_echeance:=NEW.date_credit+(v_duree||' months')::interval;
 RETURN NEW;
END $$;
CREATE TRIGGER trg_credit_before_insert BEFORE INSERT ON credits FOR EACH ROW EXECUTE FUNCTION fn_credit_before_insert();

CREATE OR REPLACE FUNCTION fn_credit_after_insert() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN INSERT INTO mouvements_caisse(cycle_id,seance_id,membre_id,type_mouvement,montant,sens,credit_id,description,date_mouvement) VALUES(NEW.cycle_id,NEW.seance_id,NEW.membre_id,'CREDIT',NEW.montant_capital,'SORTIE',NEW.id,'Sortie de caisse pour octroi du credit',NEW.date_credit); RETURN NEW; END $$;
CREATE TRIGGER trg_credit_after_insert AFTER INSERT ON credits FOR EACH ROW EXECUTE FUNCTION fn_credit_after_insert();

CREATE OR REPLACE FUNCTION fn_cycle_before_insert() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_nb INTEGER; v_ouvert INTEGER;
BEGIN
 IF NEW.statut='OUVERT' THEN
  SELECT COUNT(*) INTO v_nb FROM membres WHERE voamami_id=NEW.voamami_id AND actif=1;
  IF v_nb<15 OR v_nb>25 THEN RAISE EXCEPTION 'Un cycle ouvert doit avoir entre 15 et 25 membres actifs.'; END IF;
  SELECT COUNT(*) INTO v_ouvert FROM cycles WHERE voamami_id=NEW.voamami_id AND statut='OUVERT';
  IF v_ouvert>0 THEN RAISE EXCEPTION 'Ce VOAMAMY possede deja un cycle ouvert.'; END IF;
 END IF; RETURN NEW;
END $$;
CREATE TRIGGER trg_cycle_before_insert BEFORE INSERT ON cycles FOR EACH ROW EXECUTE FUNCTION fn_cycle_before_insert();

CREATE OR REPLACE FUNCTION fn_cycle_after_insert() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN IF NEW.statut='OUVERT' THEN UPDATE membres SET cycle_actif_id=NEW.id,solde_epargne=0 WHERE voamami_id=NEW.voamami_id AND actif=1; END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_cycle_after_insert AFTER INSERT ON cycles FOR EACH ROW EXECUTE FUNCTION fn_cycle_after_insert();

CREATE OR REPLACE FUNCTION fn_cycle_before_update() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_nb INTEGER; v_ouvert INTEGER;
BEGIN
 IF OLD.statut='CLOTURE' AND NEW.statut<>'CLOTURE' THEN RAISE EXCEPTION 'Un cycle cloture ne peut pas etre rouvert.'; END IF;
 IF OLD.statut<>'OUVERT' AND NEW.statut='OUVERT' THEN
  SELECT COUNT(*) INTO v_nb FROM membres WHERE voamami_id=NEW.voamami_id AND actif=1;
  IF v_nb<15 OR v_nb>25 THEN RAISE EXCEPTION 'Il faut entre 15 et 25 membres actifs.'; END IF;
  SELECT COUNT(*) INTO v_ouvert FROM cycles WHERE voamami_id=NEW.voamami_id AND statut='OUVERT' AND id<>NEW.id;
  IF v_ouvert>0 THEN RAISE EXCEPTION 'Un autre cycle est deja ouvert.'; END IF;
 END IF; RETURN NEW;
END $$;
CREATE TRIGGER trg_cycle_before_update BEFORE UPDATE ON cycles FOR EACH ROW EXECUTE FUNCTION fn_cycle_before_update();

CREATE OR REPLACE FUNCTION fn_cycle_after_update() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN IF OLD.statut<>'OUVERT' AND NEW.statut='OUVERT' THEN UPDATE membres SET cycle_actif_id=NEW.id,solde_epargne=0 WHERE voamami_id=NEW.voamami_id AND actif=1; END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_cycle_after_update AFTER UPDATE ON cycles FOR EACH ROW EXECUTE FUNCTION fn_cycle_after_update();

CREATE OR REPLACE FUNCTION fn_epargne_before_insert() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_part NUMERIC(15,2); v_statut VARCHAR(20); v_cycle_seance BIGINT; v_statut_seance VARCHAR(20); v_cycle_membre BIGINT;
BEGIN
 SELECT montant_part_epargne,statut INTO v_part,v_statut FROM cycles WHERE id=NEW.cycle_id;
 IF v_statut IS DISTINCT FROM 'OUVERT' THEN RAISE EXCEPTION 'Le cycle doit etre ouvert.'; END IF;
 SELECT cycle_id,statut INTO v_cycle_seance,v_statut_seance FROM seances WHERE id=NEW.seance_id;
 IF v_cycle_seance IS DISTINCT FROM NEW.cycle_id THEN RAISE EXCEPTION 'La seance ne correspond pas au cycle.'; END IF;
 IF v_statut_seance IS DISTINCT FROM 'OUVERTE' THEN RAISE EXCEPTION 'La seance est deja cloturee.'; END IF;
 SELECT cycle_actif_id INTO v_cycle_membre FROM membres WHERE id=NEW.membre_id AND actif=1;
 IF v_cycle_membre IS DISTINCT FROM NEW.cycle_id THEN RAISE EXCEPTION 'Le membre ne correspond pas au cycle actif.'; END IF;
 NEW.montant_part:=v_part; NEW.montant_total:=NEW.nombre_parts*NEW.montant_part; RETURN NEW;
END $$;
CREATE TRIGGER trg_epargne_before_insert BEFORE INSERT ON epargnes FOR EACH ROW EXECUTE FUNCTION fn_epargne_before_insert();

CREATE OR REPLACE FUNCTION fn_epargne_after_insert() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_solde NUMERIC(15,2);
BEGIN
 SELECT COALESCE(SUM(montant_total),0) INTO v_solde FROM epargnes WHERE cycle_id=NEW.cycle_id AND membre_id=NEW.membre_id;
 UPDATE membres SET solde_epargne=v_solde WHERE id=NEW.membre_id;
 SELECT NEW.cycle_id,NEW.seance_id,NEW.membre_id,COALESCE(SUM(nombre_parts),0),COALESCE(SUM(CASE WHEN seance_id=NEW.seance_id THEN montant_total ELSE 0 END),0),v_solde FROM epargnes WHERE cycle_id=NEW.cycle_id AND membre_id=NEW.membre_id
 ON CONFLICT(seance_id,membre_id) DO UPDATE SET parts_cumulees=EXCLUDED.parts_cumulees,epargne_seance=EXCLUDED.epargne_seance,solde_epargne=EXCLUDED.solde_epargne;
 RETURN NEW;
END $$;
CREATE TRIGGER trg_epargne_after_insert AFTER INSERT ON epargnes FOR EACH ROW EXECUTE FUNCTION fn_epargne_after_insert();

CREATE OR REPLACE FUNCTION fn_epargne_after_caisse() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN INSERT INTO mouvements_caisse(cycle_id,seance_id,membre_id,type_mouvement,montant,sens,epargne_id,description,date_mouvement) VALUES(NEW.cycle_id,NEW.seance_id,NEW.membre_id,'EPARGNE',NEW.montant_total,'ENTREE',NEW.id,'Depot d epargne du membre',NEW.date_epargne); RETURN NEW; END $$;
CREATE TRIGGER trg_epargne_after_caisse AFTER INSERT ON epargnes FOR EACH ROW EXECUTE FUNCTION fn_epargne_after_caisse();

CREATE OR REPLACE FUNCTION fn_membre_before_insert() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_nb INTEGER; v_cycle BIGINT;
BEGIN
 SELECT COUNT(*) INTO v_nb FROM membres WHERE voamami_id=NEW.voamami_id AND actif=1;
 IF v_nb>=25 THEN RAISE EXCEPTION 'Un VOAMAMY ne peut pas depasser 25 membres actifs.'; END IF;
 IF NEW.numero_membre<1 OR NEW.numero_membre>25 THEN RAISE EXCEPTION 'Le numero du membre doit etre compris entre 1 et 25.'; END IF;
 IF NEW.role_bureau='PRESIDENT' AND NEW.numero_membre<>1 THEN RAISE EXCEPTION 'Le President doit etre le membre numero 1.'; END IF;
 IF NEW.role_bureau='SECRETAIRE' AND NEW.numero_membre<>2 THEN RAISE EXCEPTION 'Le Secretaire doit etre le membre numero 2.'; END IF;
 IF NEW.role_bureau='TRESORIER' AND NEW.numero_membre<>3 THEN RAISE EXCEPTION 'Le Tresorier doit etre le membre numero 3.'; END IF;
 IF NEW.role_bureau='MEMBRE' AND NEW.numero_membre IN (1,2,3) THEN RAISE EXCEPTION 'Les numeros 1, 2 et 3 sont reserves au bureau.'; END IF;
 SELECT id INTO v_cycle FROM cycles WHERE voamami_id=NEW.voamami_id AND statut='OUVERT' LIMIT 1;
 NEW.cycle_actif_id:=v_cycle; NEW.solde_epargne:=0; RETURN NEW;
END $$;
CREATE TRIGGER trg_membre_before_insert BEFORE INSERT ON membres FOR EACH ROW EXECUTE FUNCTION fn_membre_before_insert();

CREATE OR REPLACE FUNCTION fn_partage_before_insert() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN NEW.montant_total_partage:=NEW.capital_membre+NEW.part_interets+NEW.part_penalites; RETURN NEW; END $$;
CREATE TRIGGER trg_partage_before_insert BEFORE INSERT ON partage_benefices FOR EACH ROW EXECUTE FUNCTION fn_partage_before_insert();

CREATE OR REPLACE FUNCTION fn_penalite_before_insert() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_montant NUMERIC(15,2); v_cycle_statut VARCHAR(20); v_cycle_seance BIGINT; v_statut_seance VARCHAR(20); v_voamami_cycle BIGINT; v_voamami_membre BIGINT; v_actif SMALLINT;
BEGIN
 SELECT montant_penalite,statut,voamami_id INTO v_montant,v_cycle_statut,v_voamami_cycle FROM cycles WHERE id=NEW.cycle_id;
 IF v_montant IS NULL THEN RAISE EXCEPTION 'Le cycle indiqué pour la pénalité n''existe pas.'; END IF;
 IF v_cycle_statut<>'OUVERT' THEN RAISE EXCEPTION 'Une pénalité ne peut être enregistrée que sur un cycle ouvert.'; END IF;
 SELECT cycle_id,statut INTO v_cycle_seance,v_statut_seance FROM seances WHERE id=NEW.seance_id;
 IF v_cycle_seance IS NULL THEN RAISE EXCEPTION 'La séance indiquée pour la pénalité n''existe pas.'; END IF;
 IF v_cycle_seance<>NEW.cycle_id THEN RAISE EXCEPTION 'La séance ne correspond pas au cycle de la pénalité.'; END IF;
 IF v_statut_seance<>'OUVERTE' THEN RAISE EXCEPTION 'Une pénalité ne peut pas être enregistrée sur une séance clôturée.'; END IF;
 SELECT voamami_id,actif INTO v_voamami_membre,v_actif FROM membres WHERE id=NEW.membre_id;
 IF v_voamami_membre IS NULL THEN RAISE EXCEPTION 'Le membre indiqué pour la pénalité n''existe pas.'; END IF;
 IF v_actif<>1 THEN RAISE EXCEPTION 'Une pénalité ne peut être attribuée qu''à un membre actif.'; END IF;
 IF v_voamami_membre<>v_voamami_cycle THEN RAISE EXCEPTION 'Le membre n''appartient pas au VOAMAMI du cycle.'; END IF;
 NEW.montant:=v_montant; RETURN NEW;
END $$;
CREATE TRIGGER trg_penalite_before_insert BEFORE INSERT ON penalites FOR EACH ROW EXECUTE FUNCTION fn_penalite_before_insert();

CREATE OR REPLACE FUNCTION fn_penalite_after_insert() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN IF NEW.statut='PAYEE' AND NEW.montant>0 THEN INSERT INTO mouvements_caisse(cycle_id,seance_id,membre_id,type_mouvement,montant,sens,penalite_id,description,date_mouvement) VALUES(NEW.cycle_id,NEW.seance_id,NEW.membre_id,'PENALITE',NEW.montant,'ENTREE',NEW.id,'Pénalité encaissée',NEW.date_penalite); END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_penalite_after_insert AFTER INSERT ON penalites FOR EACH ROW EXECUTE FUNCTION fn_penalite_after_insert();

CREATE OR REPLACE FUNCTION fn_penalite_before_update() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_statut_seance VARCHAR(20); v_cycle_seance BIGINT; v_montant NUMERIC(15,2);
BEGIN
 NEW.cycle_id:=OLD.cycle_id; NEW.seance_id:=OLD.seance_id; NEW.membre_id:=OLD.membre_id; NEW.date_penalite:=OLD.date_penalite;
 SELECT montant_penalite INTO v_montant FROM cycles WHERE id=OLD.cycle_id; NEW.montant:=v_montant;
 SELECT cycle_id,statut INTO v_cycle_seance,v_statut_seance FROM seances WHERE id=OLD.seance_id;
 IF v_cycle_seance<>OLD.cycle_id THEN RAISE EXCEPTION 'La séance ne correspond pas au cycle.'; END IF;
 IF v_statut_seance<>'OUVERTE' AND NEW.statut<>OLD.statut THEN RAISE EXCEPTION 'Une pénalité d''une séance clôturée ne peut plus être modifiée.'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER trg_penalite_before_update BEFORE UPDATE ON penalites FOR EACH ROW EXECUTE FUNCTION fn_penalite_before_update();

CREATE OR REPLACE FUNCTION fn_penalite_after_update() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF OLD.statut='IMPAYEE' AND NEW.statut='PAYEE' AND NEW.montant>0 AND NOT EXISTS(SELECT 1 FROM mouvements_caisse WHERE penalite_id=NEW.id AND type_mouvement='PENALITE') THEN
 END IF; RETURN NEW;
END $$;
CREATE TRIGGER trg_penalite_after_update AFTER UPDATE ON penalites FOR EACH ROW EXECUTE FUNCTION fn_penalite_after_update();

CREATE OR REPLACE FUNCTION fn_remboursement_before_insert() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_cycle_credit BIGINT; v_membre_credit BIGINT; v_capital NUMERIC(15,2); v_interet NUMERIC(15,2); v_principal NUMERIC(15,2); v_interet_deja NUMERIC(15,2); v_cycle_seance BIGINT;
BEGIN
 SELECT cycle_id,membre_id,montant_capital,montant_interet INTO v_cycle_credit,v_membre_credit,v_capital,v_interet FROM credits WHERE id=NEW.credit_id;
 IF v_cycle_credit IS DISTINCT FROM NEW.cycle_id THEN RAISE EXCEPTION 'Le cycle du remboursement ne correspond pas au credit.'; END IF;
 IF v_membre_credit IS DISTINCT FROM NEW.membre_id THEN RAISE EXCEPTION 'Le membre du remboursement ne correspond pas au credit.'; END IF;
 SELECT cycle_id INTO v_cycle_seance FROM seances WHERE id=NEW.seance_id;
 IF v_cycle_seance IS DISTINCT FROM NEW.cycle_id THEN RAISE EXCEPTION 'La seance ne correspond pas au cycle.'; END IF;
 SELECT COALESCE(SUM(montant_principal),0),COALESCE(SUM(montant_interet),0) INTO v_principal,v_interet_deja FROM remboursements WHERE credit_id=NEW.credit_id;
 IF v_principal+NEW.montant_principal>v_capital THEN RAISE EXCEPTION 'Le remboursement depasse le capital du credit.'; END IF;
 IF v_interet_deja+NEW.montant_interet>v_interet THEN RAISE EXCEPTION 'Le remboursement depasse les interets du credit.'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER trg_remboursement_before_insert BEFORE INSERT ON remboursements FOR EACH ROW EXECUTE FUNCTION fn_remboursement_before_insert();

CREATE OR REPLACE FUNCTION fn_remboursement_after_insert() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_capital NUMERIC(15,2); v_interet NUMERIC(15,2); v_total_principal NUMERIC(15,2); v_total_interet NUMERIC(15,2);
BEGIN
 IF NEW.montant_principal>0 THEN INSERT INTO mouvements_caisse(cycle_id,seance_id,membre_id,type_mouvement,montant,sens,remboursement_id,description,date_mouvement) VALUES(NEW.cycle_id,NEW.seance_id,NEW.membre_id,'REMBOURSEMENT_CAPITAL',NEW.montant_principal,'ENTREE',NEW.id,'Retour du capital rembourse',NEW.date_remboursement); END IF;
 IF NEW.montant_interet>0 THEN INSERT INTO mouvements_caisse(cycle_id,seance_id,membre_id,type_mouvement,montant,sens,remboursement_id,description,date_mouvement) VALUES(NEW.cycle_id,NEW.seance_id,NEW.membre_id,'REMBOURSEMENT_INTERET',NEW.montant_interet,'ENTREE',NEW.id,'Interet encaisse sur remboursement',NEW.date_remboursement); END IF;
 SELECT montant_capital,montant_interet INTO v_capital,v_interet FROM credits WHERE id=NEW.credit_id;
 SELECT COALESCE(SUM(montant_principal),0),COALESCE(SUM(montant_interet),0) INTO v_total_principal,v_total_interet FROM remboursements WHERE credit_id=NEW.credit_id;
 IF v_total_principal>=v_capital AND v_total_interet>=v_interet THEN UPDATE credits SET statut='REMBOURSE' WHERE id=NEW.credit_id; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER trg_remboursement_after_insert AFTER INSERT ON remboursements FOR EACH ROW EXECUTE FUNCTION fn_remboursement_after_insert();


-- Mise à jour automatique des colonnes updated_at (équivalent de ON UPDATE CURRENT_TIMESTAMP)
CREATE OR REPLACE FUNCTION fn_set_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN NEW.updated_at := CURRENT_TIMESTAMP; RETURN NEW; END $$;
CREATE TRIGGER trg_cycles_updated_at BEFORE UPDATE ON cycles FOR EACH ROW EXECUTE FUNCTION fn_set_updated_at();
CREATE TRIGGER trg_membres_updated_at BEFORE UPDATE ON membres FOR EACH ROW EXECUTE FUNCTION fn_set_updated_at();
CREATE TRIGGER trg_utilisateurs_updated_at BEFORE UPDATE ON utilisateurs FOR EACH ROW EXECUTE FUNCTION fn_set_updated_at();
CREATE TRIGGER trg_voamami_updated_at BEFORE UPDATE ON voamami FOR EACH ROW EXECUTE FUNCTION fn_set_updated_at();


-- ============================ PROCEDURES ============================
CREATE OR REPLACE PROCEDURE calculer_partage_cycle(p_cycle_id BIGINT) LANGUAGE plpgsql AS $$
DECLARE v_statut VARCHAR(20); v_total_epargne NUMERIC(15,2):=0; v_total_interets NUMERIC(15,2):=0; v_total_penalites NUMERIC(15,2):=0;
BEGIN
 SELECT statut INTO v_statut FROM cycles WHERE id=p_cycle_id;
 IF v_statut IS DISTINCT FROM 'CLOTURE' THEN RAISE EXCEPTION 'Le cycle doit etre cloture avant le partage.'; END IF;
 SELECT COALESCE(SUM(montant_total),0) INTO v_total_epargne FROM epargnes WHERE cycle_id=p_cycle_id;
 SELECT COALESCE(SUM(montant_interet),0) INTO v_total_interets FROM remboursements WHERE cycle_id=p_cycle_id;
 SELECT COALESCE(SUM(montant),0) INTO v_total_penalites FROM penalites WHERE cycle_id=p_cycle_id AND statut='PAYEE';
 DELETE FROM partage_benefices WHERE cycle_id=p_cycle_id;
 SELECT p_cycle_id,e.membre_id,e.total_epargne,CASE WHEN v_total_epargne>0 THEN v_total_interets*e.total_epargne/v_total_epargne ELSE 0 END,CASE WHEN v_total_epargne>0 THEN v_total_penalites*e.total_epargne/v_total_epargne ELSE 0 END,e.total_epargne+CASE WHEN v_total_epargne>0 THEN v_total_interets*e.total_epargne/v_total_epargne ELSE 0 END+CASE WHEN v_total_epargne>0 THEN v_total_penalites*e.total_epargne/v_total_epargne ELSE 0 END,CURRENT_DATE FROM v_epargne_membre_cycle e WHERE e.cycle_id=p_cycle_id AND e.total_epargne>0;
END $$;

CREATE OR REPLACE PROCEDURE cloturer_cycle(p_cycle_id BIGINT) LANGUAGE plpgsql AS $$
DECLARE v_statut VARCHAR(20); v_total INTEGER; v_cloturees INTEGER; v_non_soldes INTEGER;
BEGIN
 SELECT statut INTO v_statut FROM cycles WHERE id=p_cycle_id;
 IF v_statut IS DISTINCT FROM 'OUVERT' THEN RAISE EXCEPTION 'Le cycle doit etre ouvert.'; END IF;
 SELECT COUNT(*) INTO v_total FROM seances WHERE cycle_id=p_cycle_id; SELECT COUNT(*) INTO v_cloturees FROM seances WHERE cycle_id=p_cycle_id AND statut='CLOTUREE';
 IF v_total<>v_cloturees THEN RAISE EXCEPTION 'Toutes les seances doivent etre cloturees avant le cycle.'; END IF;
 SELECT COUNT(*) INTO v_non_soldes FROM credits WHERE cycle_id=p_cycle_id AND statut<>'REMBOURSE';
 IF v_non_soldes>0 THEN RAISE EXCEPTION 'Des credits ne sont pas encore solde : cloture du cycle impossible.'; END IF;
 UPDATE cycles SET statut='CLOTURE',date_cloture=CURRENT_DATE WHERE id=p_cycle_id;
 CALL calculer_partage_cycle(p_cycle_id);
END $$;

CREATE OR REPLACE PROCEDURE cloturer_seance(p_seance_id BIGINT) LANGUAGE plpgsql AS $$
DECLARE v_cycle_id BIGINT; v_voamami_id BIGINT; v_statut VARCHAR(20);
BEGIN
 SELECT s.cycle_id,c.voamami_id,s.statut INTO v_cycle_id,v_voamami_id,v_statut FROM seances s JOIN cycles c ON c.id=s.cycle_id WHERE s.id=p_seance_id;
 IF v_statut IS NULL THEN RAISE EXCEPTION 'Seance introuvable.'; END IF;
 IF v_statut='CLOTUREE' THEN RAISE EXCEPTION 'La seance est deja cloturee.'; END IF;
 SELECT v_cycle_id,p_seance_id,m.id,COALESCE((SELECT SUM(e.nombre_parts) FROM epargnes e WHERE e.cycle_id=v_cycle_id AND e.membre_id=m.id),0),COALESCE((SELECT SUM(e.montant_total) FROM epargnes e WHERE e.cycle_id=v_cycle_id AND e.seance_id=p_seance_id AND e.membre_id=m.id),0),COALESCE((SELECT SUM(e.montant_total) FROM epargnes e WHERE e.cycle_id=v_cycle_id AND e.membre_id=m.id),0) FROM membres m WHERE m.voamami_id=v_voamami_id AND m.actif=1
 ON CONFLICT(seance_id,membre_id) DO UPDATE SET parts_cumulees=EXCLUDED.parts_cumulees,epargne_seance=EXCLUDED.epargne_seance,solde_epargne=EXCLUDED.solde_epargne,date_enregistrement=CURRENT_TIMESTAMP;
 UPDATE seances SET statut='CLOTUREE' WHERE id=p_seance_id;
END $$;


-- ============================ VUES ============================
CREATE OR REPLACE VIEW v_epargne_membre_cycle AS
SELECT m.id AS membre_id,m.numero_membre,m.nom,m.prenom,m.role_bureau,c.id AS cycle_id,c.numero_cycle,COALESCE(SUM(e.nombre_parts),0) AS total_parts,COALESCE(SUM(e.montant_total),0) AS total_epargne
FROM membres m JOIN cycles c ON c.voamami_id=m.voamami_id LEFT JOIN epargnes e ON e.membre_id=m.id AND e.cycle_id=c.id
GROUP BY m.id,m.numero_membre,m.nom,m.prenom,m.role_bureau,c.id,c.numero_cycle;

CREATE OR REPLACE VIEW v_historique_solde_epargne AS
SELECT s.id AS solde_id,s.cycle_id,c.numero_cycle,s.seance_id,se.numero_seance,se.date_seance,s.membre_id,m.numero_membre,m.nom,m.prenom,s.parts_cumulees,s.epargne_seance,s.solde_epargne,s.date_enregistrement
FROM soldes_epargne_seance s JOIN cycles c ON c.id=s.cycle_id JOIN seances se ON se.id=s.seance_id JOIN membres m ON m.id=s.membre_id;

CREATE OR REPLACE VIEW v_interets_encaissement_cycle AS
SELECT cycle_id,COALESCE(SUM(montant_interet),0) AS total_interets FROM remboursements GROUP BY cycle_id;

CREATE OR REPLACE VIEW v_mouvements_caisse AS
SELECT mc.id,mc.cycle_id,c.numero_cycle,mc.seance_id,s.numero_seance,mc.membre_id,m.nom,m.prenom,mc.type_mouvement,mc.montant,mc.sens,mc.description,mc.date_mouvement
FROM mouvements_caisse mc JOIN cycles c ON c.id=mc.cycle_id JOIN seances s ON s.id=mc.seance_id LEFT JOIN membres m ON m.id=mc.membre_id;

CREATE OR REPLACE VIEW v_penalites_encaissement_cycle AS
SELECT cycle_id,COALESCE(SUM(CASE WHEN statut='PAYEE' THEN montant ELSE 0 END),0) AS total_penalites FROM penalites GROUP BY cycle_id;

CREATE OR REPLACE VIEW v_resume_cycle AS
SELECT c.id AS cycle_id,c.voamami_id,v.nom AS voamamy,c.numero_cycle,c.date_debut,c.date_fin_prevue,c.date_cloture,c.statut,c.montant_part_epargne,c.taux_interet,c.duree_credit_mois,
 (SELECT COUNT(*) FROM membres m WHERE m.voamami_id=c.voamami_id AND m.actif=1) AS nombre_membres,
 (SELECT COALESCE(SUM(e.montant_total),0) FROM epargnes e WHERE e.cycle_id=c.id) AS total_epargne,
 (SELECT COALESCE(SUM(cr.montant_capital),0) FROM credits cr WHERE cr.cycle_id=c.id) AS total_credits,
 (SELECT COALESCE(SUM(r.montant),0) FROM remboursements r WHERE r.cycle_id=c.id) AS total_remboursements,
 (SELECT COALESCE(SUM(r.montant_interet),0) FROM remboursements r WHERE r.cycle_id=c.id) AS total_interets,
 (SELECT COALESCE(SUM(p.montant),0) FROM penalites p WHERE p.cycle_id=c.id AND p.statut='PAYEE') AS total_penalites,
 (SELECT COALESCE(SUM(CASE WHEN mc.sens='ENTREE' THEN mc.montant ELSE -mc.montant END),0) FROM mouvements_caisse mc WHERE mc.cycle_id=c.id) AS solde_caisse
FROM cycles c JOIN voamami v ON v.id=c.voamami_id;

CREATE OR REPLACE VIEW v_situation_credits AS
SELECT c.id AS credit_id,c.cycle_id,c.seance_id,c.membre_id,m.numero_membre,m.nom,m.prenom,a.libelle AS motif_agr,c.date_credit,c.montant_capital,c.montant_interet,c.montant_total,c.date_echeance,c.statut AS statut_enregistre,COALESCE(SUM(r.montant),0) AS total_rembourse,c.montant_total-COALESCE(SUM(r.montant),0) AS reste_a_payer,
 CASE WHEN COALESCE(SUM(r.montant),0)>=c.montant_total THEN 'REMBOURSE' WHEN CURRENT_DATE>c.date_echeance AND COALESCE(SUM(r.montant),0)<c.montant_total THEN 'EN_RETARD' ELSE 'EN_COURS' END AS situation_calculee
FROM credits c JOIN membres m ON m.id=c.membre_id LEFT JOIN agr a ON a.id=c.agr_id LEFT JOIN remboursements r ON r.credit_id=c.id
GROUP BY c.id,c.cycle_id,c.seance_id,c.membre_id,m.numero_membre,m.nom,m.prenom,a.libelle,c.date_credit,c.montant_capital,c.montant_interet,c.montant_total,c.date_echeance,c.statut;

CREATE OR REPLACE VIEW v_solde_caisse_cycle AS
SELECT c.id AS cycle_id,c.voamami_id,c.numero_cycle,COALESCE(SUM(CASE WHEN mc.sens='ENTREE' THEN mc.montant ELSE -mc.montant END),0) AS solde_caisse FROM cycles c LEFT JOIN mouvements_caisse mc ON mc.cycle_id=c.id GROUP BY c.id,c.voamami_id,c.numero_cycle;

CREATE OR REPLACE VIEW v_solde_epargne_membre AS
SELECT m.id AS membre_id,m.voamami_id,m.numero_membre,m.nom,m.prenom,m.role_bureau,m.cycle_actif_id,c.numero_cycle,m.solde_epargne FROM membres m LEFT JOIN cycles c ON c.id=m.cycle_actif_id;

COMMIT;
